export function AdaptationCenter({go,announce}:SurfaceProps){return <><Banner icon={RefreshCw} title="Adaptation Engine Control Center" detail="See what the system learned, what it wants to change, and what is ready for promotion." tone="amber"/><div className="adaptation-kpis"><Stat value="12,842" label="Experiences processed"/><Stat value="87" label="Candidate improvements"/><Stat value="34" label="Validated skills"/><Stat value="09" label="Active experiments"/><Stat value="04" label="Pending promotions" tone="warning"/></div><div className="section-grid two-one"><Card><Head title="Promotion queue" sub="Evidence-backed candidates"/><div className="candidate-card"><div className="candidate-heading"><Pill tone="positive">Candidate Skill #182</Pill><span className="confidence">173 jobs</span></div><h3>Short identity batch v4</h3><p>Reduce identity drift by shortening scene batches while preserving the tactile opening.</p><div className="rate-compare"><span><small>Old success rate</small><b>87.3%</b></span><ArrowRight size={17}/><span><small>New projected rate</small><b className="positive-text">92.1%</b></span></div><div className="test-list"><span><Check size={13}/> Golden tests</span><span><Check size={13}/> Fresh tests</span><span><Check size={13}/> Adversarial tests</span><span><Check size={13}/> Regression tests</span></div><button className="primary-button full-button" onClick={()=>announce('Candidate skill promotion staged locally.')}>Promote candidate</button></div></Card><Card><Head title="Engine learning signals" sub="What changed recently"/><Row icon={GitCompare} title="Model affinity update" detail="Cosmos Reason 2 preferred for identity scenes" status="14 updates" tone="sage"/><Row icon={Sparkles} title="Prompt pattern update" detail="Gesture-first hooks outperform context-first hooks" status="Strong" tone="coral"/><Row icon={WandSparkles} title="User preference update" detail="Direct language promoted to campaign scope" status="Scoped" tone="amber"/><button className="soft-action" onClick={()=>go('evolution')}>Open evolution history <ArrowRight size={14}/></button></Card></div></>}

export function SkillDiff({inspect}:SurfaceProps){return <><Banner icon={GitCompare} title="Skill Version Diff" detail="Compare creative intelligence like a Git diff before promoting it." tone="slate"/><div className="diff-header"><div><span className="panel-kicker">Comparing</span><h2>Character Consistency <span>v7 → v8</span></h2></div><Pill tone="positive">Regression tests passed</Pill></div><div className="diff-grid"><Card><Head title="Character Consistency v7" sub="Previous version"/><DiffLine label="Prompt change" value="Single reference image" tone="removed"/><DiffLine label="Tool change" value="No identity verifier" tone="removed"/><DiffLine label="Model preference" value="Generic image edit" tone="removed"/><DiffLine label="Success rate" value="87.3%" tone="removed"/></Card><Card><Head title="Character Consistency v8" sub="Candidate version"/><DiffLine label="Prompt change" value="Canonical pack + constraints" tone="added"/><DiffLine label="Tool change" value="Identity verifier v2" tone="added"/><DiffLine label="Model preference" value="Qwen Image Edit" tone="added"/><DiffLine label="Success rate" value="92.1%" tone="added"/></Card></div><Card><Head title="Validation" sub="A promotion requires all gates"/><div className="security-strip"><Pill tone="positive"><Check size={13}/> Golden tests</Pill><Pill tone="positive"><Check size={13}/> Fresh tests</Pill><Pill tone="positive"><Check size={13}/> Adversarial tests</Pill><Pill tone="positive"><Check size={13}/> Regression tests</Pill></div><button className="primary-button" onClick={()=>inspect('skill','Character Consistency v8','The candidate is ready for evidence-backed promotion.')}>Inspect promotion record <ArrowRight size={14}/></button></Card></>}
function DiffLine({label,value,tone}:{label:string;value:string;tone:string}){return <div className={`diff-line ${tone}`}><span>{tone==='added'?'+':'-'} {label}</span><b>{value}</b></div>}

export function GenomeCompare({}:SurfaceProps){const [a,setA]=useState('AI Storytelling Genome');const [b,setB]=useState('Food Advertising Genome');return <><Banner icon={GitCompare} title="Creative Genome Comparison" detail="Compare reusable creative grammar across niches and modes." tone="coral"/><div className="compare-selectors"><label>Genome A<select value={a} onChange={e=>setA(e.target.value)}><option>AI Storytelling Genome</option><option>Cinematic Food Genome</option></select></label><GitCompare size={20}/><label>Genome B<select value={b} onChange={e=>setB(e.target.value)}><option>Food Advertising Genome</option><option>Documentary Field Genome</option></select></label></div><Card><Head title="Grammar comparison" sub={`${a} vs ${b}`}/><div className="comparison-table"><div className="comparison-head"><span>Pattern</span><b>{a}</b><b>{b}</b></div>{[['Hook','Question → tension','Gesture → appetite'],['Pacing','Escalating beats','Deliberate first 04s'],['Visual Grammar','Subject-led framing','Warm edge close crop'],['Audio Grammar','Voice-led rhythm','Room tone + cue'],['CTA','Open question','Conversational invitation'],['Emotion','Curiosity → resolve','Curiosity → trust'],['Audience','Story seekers','Food craft audience']].map(x=><div className="comparison-row" key={x[0]}><span>{x[0]}</span><b>{x[1]}</b><b>{x[2]}</b></div>)}</div></Card></>}

export function CreativeMode({go,announce}:SurfaceProps){const modes=['Story','Advertisement','Product Commercial','Animation','Cinematic','Documentary','Social Short','Educational','Product Photography','Custom'];const [mode,setMode]=useState('Advertisement');return <><Banner icon={Sparkles} title="Creative Mode" detail="Change the creative domain and Flujo updates the relevant genome, blueprint templates, models, skills, and QA rules." tone="coral"/><div className="mode-grid">{modes.map(x=><button className={`mode-card ${mode===x?'selected':''}`} key={x} onClick={()=>{setMode(x);announce(`${x} mode selected locally.`)}}><span>{mode===x?<CheckCircle2 size={17}/>:<CircleDashed size={17}/>}</span><b>{x}</b><small>{['Narrative grammar','Campaign hooks','Product claims','Motion grammar','Cinematic language','Field observation','Fast retention','Lesson structure','Product detail','User-defined'][modes.indexOf(x)]}</small></button>)}</div><Card><Head title={`${mode} mode contract`} sub="These controls will guide later engine selection"/><div className="contract-grid"><Row icon={Sparkles} title="Genome template" detail={`${mode} grammar pack`}/><Row icon={GitCompare} title="Blueprint template" detail="30s short-form vertical"/><Row icon={Boxes} title="Preferred models" detail="Model Registry affinity group"/><Row icon={ShieldCheck} title="QA rules" detail="Identity, claims, originality, format"/></div><button className="primary-button" onClick={()=>go('chat')}>Create in this mode <ArrowRight size={14}/></button></Card></>}

export function SourceMonitor({announce}:SurfaceProps){const [auto,setAuto]=useState(true);return <><Banner icon={Globe2} title="Source Monitor" detail="Watch external inspiration sources separately from infrastructure observability." tone="slate"/><div className="monitor-source-grid"><Card className="source-card"><div className="source-head"><div className="source-avatar"><Globe2 size={18}/></div><div><b>@creator / Instagram</b><small>Food craft reference source</small></div><Pill tone="positive"><span/> Monitoring</Pill></div><div className="source-stats"><span>Last checked <b>10:00</b></span><span>New posts <b>02</b></span></div><div className="source-toggles"><Toggle label="Auto-analyze" enabled={auto} onClick={()=>setAuto(!auto)}/><Toggle label="Auto-generate" enabled onClick={()=>announce('Auto-generate remains a local preview.')}/><Toggle label="Auto-publish" enabled={false} onClick={()=>announce('Publishing is disconnected in the local shell.')}/></div></Card><Card><Head title="Source changes" sub="Recent monitored events"/><Row icon={Sparkles} title="New tactile opening" detail="@creator / post 1842" status="New" tone="coral"/><Row icon={FileStack} title="Reference pack updated" detail="8 frames normalized" status="Analyzed" tone="positive"/><Row icon={Clock3} title="Next check" detail="Monitoring schedule is local" status="15 min" tone="slate"/></Card></div></>}
function Toggle({label,enabled,onClick}:{label:string;enabled:boolean;onClick:()=>void}){return <button className={`toggle-row ${enabled?'enabled':''}`} onClick={onClick}><span className="toggle-track"><i/></span><span><b>{label}</b><small>{enabled?'On':'Off'}</small></span></button>}

export function SocialAccounts({go,announce}:SurfaceProps){return <><Banner icon={Globe2} title="Social Accounts" detail="Manage posting identity, permissions, platform rules, timezones, and publishing limits." tone="coral"/><div className="account-grid">{[['Instagram','Connected','@northstar.food','positive'],['YouTube','Connected','Northstar Food Stories','positive'],['TikTok','Not connected','No account linked','neutral'],['Facebook','Not connected','No account linked','neutral']].map(x=><Card className="account-card" key={x[0]}><div className="account-top"><span className="account-logo"><Globe2 size={20}/></span><Pill tone={x[3]}>{x[1]}</Pill></div><h3>{x[0]}</h3><p>{x[2]}</p><div className="account-meta"><span>Timezone <b>Local</b></span><span>Posting <b>{x[1]==='Connected'?'Allowed':'Blocked'}</b></span></div><button className="secondary-button full-button" onClick={()=>x[1]==='Connected'?go('publishing'):announce(`${x[0]} connection is staged locally.`)}>{x[1]==='Connected'?'Manage account':'Connect later'} <ArrowRight size={14}/></button></Card>)}</div><Card><Head title="Platform defaults" sub="Applied before a publishing job is created"/><div className="section-grid two-one"><Row icon={MessageCircle} title="Default captions" detail="Direct language with conversational CTA" tone="coral"/><Row icon={Clock3} title="Publishing windows" detail="Human review before scheduled release" tone="amber"/><Row icon={ShieldCheck} title="Permission boundary" detail="No auto-publish without approval" tone="sage"/></div></Card></>}

export function Calendar({go,announce}:SurfaceProps){const slots=[['08:00','AI Story #41','Published','positive'],['13:00','Food Ad #12','Scheduled','warning'],['19:00','Cinematic #9','QA','accent'],['Tomorrow','Recipe Voice #03','Blueprint','neutral']];return <><div className="calendar-header"><div><span className="panel-kicker">Content Calendar</span><h2>August 24 - the creative schedule</h2></div><div className="calendar-actions"><button className="secondary-button compact-button">Today</button><button className="primary-button compact-button" onClick={()=>announce('Schedule item staged locally.')}><Plus size={15}/> Schedule content</button></div></div><Card className="calendar-card"><div className="calendar-week"><span>Mon 24</span><span>Tue 25</span><span>Wed 26</span><span>Thu 27</span><span>Fri 28</span></div><div className="calendar-grid">{['08:00','13:00','19:00','Tomorrow'].map((time,i)=><div className="calendar-slot" key={time}><span>{time}</span><button className={`calendar-event ${slots[i][3]}`} onClick={()=>go(i===2?'qa':'production')}><b>{slots[i][1]}</b><small>{slots[i][2]}</small></button></div>)}</div></Card><Card><Head title="Schedule rules" sub="Automation will use these constraints later"/><Row icon={ShieldCheck} title="Human review required" detail="Every content item must pass QA before publishing" status="On" tone="positive"/><Row icon={Clock3} title="Quiet hours" detail="No publishing after 21:00 local time" status="On" tone="amber"/><Row icon={Users} title="Platform identity" detail="Northstar Food Stories / default account" status="Scoped" tone="slate"/></Card></>}

export function Resources({go}:SurfaceProps){return <><Banner icon={Gauge} title="Resource Center" detail="Make cost, latency, and advisor usage visible before the system calls expensive engines." tone="amber"/><div className="resource-kpis"><Stat value="$5.36" label="Today"/><Stat value="$37.20" label="Used this month"/><Stat value="$82.10" label="Projected" tone="warning"/><Stat value="$100" label="Monthly budget"/></div><div className="section-grid two-one"><Card><Head title="Today by resource" sub="Illustrative local cost records"/>{[['AI inference','$1.23','coral'],['Image generation','$0.84','sage'],['Video generation','$3.17','amber'],['Storage','$0.12','slate']].map(x=><div className="cost-row" key={x[0]}><span className={`cost-mark ${x[2]}`}/><b>{x[0]}</b><span>{x[1]}</span></div>)}<div className="cost-total"><b>Total</b><strong>$5.36</strong></div></Card><Card><Head title="Model cost profile" sub="Cost/job is a Governor input"/><div className="table-wrap"><table className="data-table"><thead><tr><th>Model</th><th>Usage</th><th>Cost/job</th></tr></thead><tbody>{[['Cosmos Reason 2','12 jobs','$0.84'],['Qwen Image Edit','24 jobs','$0.18'],['Nemotron Omni','08 jobs','$0.22']].map(x=><tr key={x[0]}><td>{x[0]}</td><td>{x[1]}</td><td>{x[2]}</td></tr>)}</tbody></table></div><button className="soft-action" onClick={()=>go('governor')}>Open Governor budget posture <ArrowRight size={14}/></button></Card></div><Card><Head title="Budget policy" sub="Prevent runaway advisor and generation calls"/><div className="budget-bar"><span style={{width:'37%'}}/></div><div className="meter-foot"><span>$37.20 used</span><b>$100 monthly</b></div></Card></>}

export function Credentials({announce}:SurfaceProps){return <><Banner icon={KeyRound} title="Credentials" detail="Store provider access without exposing full secrets after saving." tone="slate"/><div className="credential-grid">{[['NVIDIA','5 keys configured','nv_••••••••82F','positive'],['OpenAI','1 key configured','sk_••••••••91A','positive'],['Google','Not configured','No secret saved','neutral'],['Storage','Connected','s3_••••••••4D2','positive'],['Instagram','Connected','ig_••••••••08C','positive']].map(x=><Card className="credential-card" key={x[0]}><div className="credential-top"><FileKey2 size={19}/><Pill tone={x[3]}>{x[1].includes('configured')||x[1]==='Connected'?'Configured':'Empty'}</Pill></div><h3>{x[0]}</h3><p>{x[1]}</p><code>{x[2]}</code><div className="credential-foot"><span>Last successful call <b>{x[3]==='positive'?'Today':'Never'}</b></span><button className="secondary-button compact-button" onClick={()=>announce(`${x[0]} credential editor staged locally.`)}>Manage</button></div></Card>)}</div><Card><Head title="Credential safety" sub="Secrets are redacted and never shown in full"/><div className="security-strip"><Pill tone="positive"><Check size={13}/> Redaction enabled</Pill><Pill tone="positive"><Check size={13}/> Provider scopes visible</Pill><Pill tone="warning"><RefreshCw size={13}/> Rotation reminders staged</Pill></div></Card></>}

export function Setup({go}:SurfaceProps){const [step,setStep]=useState(0);const steps=['Workspace','Storage','NVIDIA','Other AI models','Model Society','Social accounts','Defaults','Health check','Test generation','Ready'];return <><div className="setup-shell"><div className="setup-intro"><span className="flow-mark"><i/><i/><i/></span><span className="panel-kicker">First launch / Setup Assistant</span><h2>Welcome to Flujo</h2><p>Set the boundaries first. Connect engines only when you understand what they can do.</p></div><div className="setup-steps">{steps.map((x,i)=><button key={x} className={i===step?'active':i<step?'done':''} onClick={()=>setStep(i)}><span>{i<step?<Check size={13}/>:`0${i+1}`}</span><b>{x}</b></button>)}</div><Card className="setup-card"><div className="setup-card-head"><div><span className="panel-kicker">Step {String(step+1).padStart(2,'0')} / {steps.length}</span><h2>{steps[step]}</h2></div><Pill tone={step<7?'warning':'positive'}>{step<7?'Not configured':'Ready to verify'}</Pill></div><p>{['Name the workspace and choose the first project context.','Choose local or connected storage boundaries.','Add NVIDIA access later through the redacted credential vault.','Review future providers and fallback groups.','Choose which advisors can participate in decisions.','Add social accounts only after publishing policy is explicit.','Set default creative mode, review gates, and quiet hours.','Run a local health check without external calls.','Rehearse one scene in the sandbox before enabling production.','Your workspace is ready for a controlled first vertical slice.'][step]}</p><div className="setup-actions"><button className="secondary-button" disabled={step===0} onClick={()=>setStep(step-1)}>Back</button><button className="primary-button" onClick={()=>step===steps.length-1?go('chat'):setStep(step+1)}>{step===steps.length-1?'Open Creative Chat':'Continue'} <ArrowRight size={15}/></button></div></Card></div></>}

export function Copilot({announce}:SurfaceProps){const [question,setQuestion]=useState('Why did the Governor choose Cosmos?');const [answered,setAnswered]=useState(false);return <><Banner icon={Bot} title="Flujo Copilot / Explain" detail="A persistent explanatory layer for decisions, terms, policies, and engine behavior." tone="coral"/><div className="copilot-layout"><Card><Head title="Ask for an explanation" sub="Use plain language, not hidden reasoning"/><div className="copilot-prompts">{['Why did the Governor choose Cosmos?','Why is Scene 7 blocked?','What does Adaptive Sampling mean?','Why is this skill being promoted?'].map(x=><button key={x} onClick={()=>{setQuestion(x);setAnswered(false)}}><MessageCircle size={14}/>{x}<ArrowRight size={13}/></button>)}</div><div className="copilot-input"><textarea value={question} onChange={e=>setQuestion(e.target.value)} rows={3}/><button className="primary-button" onClick={()=>{setAnswered(true);announce('Copilot explanation generated from local evidence fixtures.')}}><Send size={15}/> Explain</button></div></Card><Card className="copilot-answer"><Head title="Explanation" sub="Evidence-linked answer"/>{answered?<><Pill tone="positive"><CheckCircle2 size={13}/> Evidence attached</Pill><h3>Cosmos was selected because the current task prioritizes multimodal scene reasoning and the model has the strongest local affinity for identity continuity.</h3><div className="explain-chain"><span>Task: Scene 04 identity</span><ArrowRight size={14}/><span>Model affinity: Cosmos</span><ArrowRight size={14}/><span>Governor decision</span></div><small>This is a demo explanation. A connected backend will cite actual runs, policies, and model metrics.</small></>:<div className="empty-state"><Bot size={24}/><p>Ask a question and Flujo will explain the attached evidence chain.</p></div>}</Card></div></>}

export function Security({go,inspect}:SurfaceProps){return <><Banner icon={ShieldCheck} title="Security Center" detail="Make secret isolation, sandboxing, untrusted content, and permission boundaries visible." tone="slate"/><div className="security-score"><div className="score-ring"><span>94</span><small>demo</small></div><div><span className="panel-kicker">Protection posture</span><h2>Boundaries are visible</h2><p>One credential rotation reminder needs attention.</p></div><button className="secondary-button" onClick={()=>go('credentials')}><KeyRound size={15}/> Open credentials</button></div><div className="security-grid">{([['Secrets','Redaction and vault boundaries','positive',KeyRound],['Tool Sandbox','Ephemeral execution isolation','positive',Code2],['External Content Isolation','Quarantine untrusted references','positive',Archive],['Prompt Injection Guard','Review imported instructions','positive',ShieldCheck],['Publishing Permissions','Human approval boundary','positive',Globe2],['Credential Rotation','One reminder overdue','warning',RefreshCw]] as Array<[string,string,'positive'|'warning',any]>).map(([name,detail,tone,I])=><button className="security-card" key={name} onClick={()=>inspect('security',name,detail)}><span className={`security-icon ${tone}`}><I size={18}/></span><span><b>{name}</b><small>{detail}</small></span><Pill tone={tone}>{tone==='positive'?'Healthy':'Review'}</Pill></button>)}</div><Card><Head title="Security incidents" sub="Anything suspicious routes to Doctor and Review Queue"/><Row icon={CircleAlert} title="External content quarantined" detail="Reference note contained untrusted instructions" status="Contained" tone="positive" click={()=>go('incidents')}/><Row icon={KeyRound} title="Credential rotation reminder" detail="NVIDIA key nv_••••••••82F" status="Review" tone="warning" click={()=>go('credentials')}/></Card></>}

export function Policies({inspect}:SurfaceProps){return <><Banner icon={LockKeyhole} title="Policy Center" detail="Inspect the hierarchy that governs what the system can do and why." tone="amber"/><div className="policy-chain"><span>System</span><ArrowRight size={15}/><span>Security</span><ArrowRight size={15}/><span>Platform</span><ArrowRight size={15}/><span>User</span><ArrowRight size={15}/><span>Project</span><ArrowRight size={15}/><span>Governor</span><ArrowRight size={15}/><span>Advisor</span></div><div className="policy-grid">{[['System Policy','Core engine safety, privacy, and local-data boundaries','coral'],['Security Policy','Secrets, tools, untrusted content, and permissions','slate'],['Content Policy','Claims, originality, and platform restrictions','amber'],['Publishing Policy','Review gates, accounts, timing, and destinations','sage'],['User Preferences','Language, style, pacing, and communication','coral'],['Project Rules','Northstar-specific creative and approval constraints','amber']].map(x=><Card className={`policy-card ${x[2]}`} key={x[0]}><span className="panel-kicker">Policy scope</span><h3>{x[0]}</h3><p>{x[1]}</p><button className="text-button" onClick={()=>inspect('policy',x[0],`${x[0]} rules are inherited by Governor and advisor decisions.`)}>Inspect rules <ArrowRight size={14}/></button></Card>)}</div></>}

export function Sandbox({go,announce}:SurfaceProps){const [running,setRunning]=useState(false);return <><Banner icon={TestTube2} title="Flujo Sandbox" detail="Run plans without touching real APIs, social accounts, production data, publishing, or permanent skills." tone="sage"/><div className="sandbox-hero"><div><span className="panel-kicker">Simulation request</span><h2>Simulate generating three food ads using the current model council.</h2><p>Sandbox mode will estimate cost, runtime, advisors, models, quality, and potential failures.</p></div><button className="primary-button" onClick={()=>{setRunning(true);announce('Sandbox simulation started locally.')}}>{running?<Activity className="spin" size={16}/>:<Play size={16}/>} {running?'Running':'Run simulation'}</button></div><div className="sandbox-grid"><Card><Head title="Projected run" sub="Before any real call exists"/><Stat value="$2.52" label="Estimated cost"/><Stat value="04m 18s" label="Estimated runtime"/><Stat value="03" label="Advisors used"/><Stat value="06" label="Potential failures" tone="warning"/></Card><Card><Head title="Sandbox boundaries" sub="What cannot be touched"/><Row icon={Cloud} title="Real APIs" detail="No provider requests" status="Blocked" tone="positive"/><Row icon={Globe2} title="Social accounts" detail="No account access" status="Blocked" tone="positive"/><Row icon={Archive} title="Permanent skills" detail="No promotion from sandbox" status="Blocked" tone="positive"/><button className="soft-action" onClick={()=>go('workflow')}>Inspect sandbox workflow <ArrowRight size={14}/></button></Card></div></>}

export function Experiments({go,announce}:SurfaceProps){return <><Banner icon={FlaskConical} title="Experiment Lab" detail="Compare alternatives on quality, cost, latency, retention, and user rating before Adaptation promotes a winner." tone="coral"/><div className="experiment-header"><span><span className="panel-kicker">Experiment #42</span><h2>Citrus at Dusk / opening strategy</h2></span><Pill tone="warning">In evaluation</Pill></div><div className="experiment-grid"><ExperimentCard label="A" title="Current skill" detail="Deliberate first cut" score="82"/><ExperimentCard label="B" title="Faster pacing" detail="Shorten the hold by 01s" score="87" selected/><ExperimentCard label="C" title="Alternative hook" detail="Start with product reveal" score="76"/></div><Card><Head title="Experiment metrics" sub="Winner routes to the Adaptation Engine"/><div className="experiment-metrics"><Stat value="87" label="Quality"/><Stat value="$0.84" label="Cost"/><Stat value="2.4s" label="Latency"/><Stat value="78%" label="Retention"/><Stat value="4.2" label="User rating"/></div><button className="primary-button" onClick={()=>{announce('Experiment winner staged for adaptation review.');go('adaptationCenter')}}>Send winner to Adaptation <ArrowRight size={14}/></button></Card></>}
