export function ReviewQueue({go,inspect,announce}:SurfaceProps){const [items,setItems]=useState([['Scene 4 identity','Identity drift forecast','Blocking','doctor'],['Scene 8 audio sync','Timing mismatch','Review','production'],['Ad claim','Content policy check','Review','policies'],['Publishing permission','Account scope','Review','socialAccounts'],['Originality warning','Reference overlap','Review','evidence']]);return <><Banner icon={ClipboardList} title="Review Queue" detail="Everything uncertain comes here before it can move into automation or publishing." tone="amber"/><div className="review-queue-head"><Stat value="05" label="Needs review"/><div><Pill tone="warning"><CircleAlert size={13}/> Human checkpoint</Pill><small>Approve, reject, regenerate, or ask Governor.</small></div></div><Card><Head title="Needs review" sub="The safety valve of the creative automation system"/>{items.map((x,i)=><div className="review-item" key={x[0]}><span className="review-item-index">0{i+1}</span><span><b>{x[0]}</b><small>{x[1]}</small></span><Pill tone={x[2]==='Blocking'?'critical':'warning'}>{x[2]}</Pill><div className="review-actions"><button onClick={()=>{setItems(items.filter((_,n)=>n!==i));announce(`${x[0]} approved locally.`)}}><Check size={13}/> Approve</button><button onClick={()=>inspect('review',x[0],`${x[1]}. Ask Governor before choosing a path.`)}><Bot size={13}/> Ask Governor</button><button onClick={()=>go(x[3])}><ChevronRight size={14}/></button></div></div>)}</Card></>}
