export function MediaEngine({go,announce}:SurfaceProps){const [paused,setPaused]=useState(false);return <><Banner icon={Boxes} title="Flujo Media & Tool Engine" detail="A governed media layer for FFmpeg, FFprobe, Remotion, visual analytics, image tools, audio tools, and sandboxed execution." tone="coral"/><div className="media-engine-kpis"><Stat value="04" label="Active jobs"/><Stat value="12" label="Queued tools"/><Stat value="98%" label="Worker health" tone="positive"/><Stat value="00:14" label="Last render"/></div><div className="media-pipeline"><span><Bot size={14}/> Governor</span><ArrowRight size={14}/><span><WandSparkles size={14}/> Media Planner</span><ArrowRight size={14}/><span><Workflow size={14}/> Tool Router</span><ArrowRight size={14}/><span className="current"><Boxes size={14}/> Media Engine</span></div><div className="section-grid two-one"><Card><Head title="Engine workers" sub="The low-level and high-level media stack"/><Row icon={Terminal} title="FFmpeg" detail="Trim, concat, crop, resize, transcode, audio, subtitles" status="Ready" tone="positive" click={()=>go('mediaTools')}/><Row icon={Search} title="FFprobe" detail="Duration, FPS, audio, resolution, codec metadata" status="Ready" tone="positive" click={()=>go('terminal')}/><Row icon={Sparkles} title="Remotion" detail="Compositions, captions, overlays, transitions, timelines" status="Ready" tone="coral" click={()=>go('composition')}/><Row icon={BrainCircuitIcon} title="DeepStream / CUDA" detail="High-throughput visual analytics boundary" status="Planned" tone="slate"/></Card><Card><Head title="Active media work" sub="Citrus at Dusk / Scene 04"/><div className="media-preview-stage"><div className="media-preview-orb"><Boxes size={28}/><span>{paused?'Paused':'Rendering'}</span></div><div className="media-preview-lines"><i/><i/><i/></div><button className="motherboard-pause" aria-label={paused?'Resume media render':'Pause media render'} onClick={()=>{setPaused(!paused);announce(paused?'Media render resumed locally.':'Media render paused locally.')}}><span className="board-chip"><i/><i/></span>{paused?<Play size={18}/>:<span className="pause-glyph"><i/><i/></span>}</button></div><div className="media-meta"><span>Status <b>{paused?'Paused':'Rendering'}</b></span><span>Frames <b>{paused?'142':'188'} / 240</b></span><span>Output <b>scene_04_preview.mp4</b></span></div><button className="soft-action" onClick={()=>go('replay')}>Open agent activity replay <ArrowRight size={14}/></button></Card></div><Card><Head title="Media engine policy" sub="The Governor never executes raw shell commands"/><div className="security-strip"><Pill tone="positive"><Check size={13}/> Tool API only</Pill><Pill tone="positive"><Check size={13}/> Sandbox boundary</Pill><Pill tone="warning"><CircleAlert size={13}/> Human gate for host access</Pill></div></Card></>}

export function MediaTools({go,inspect}:SurfaceProps){const categories=[['Analysis',['ffprobe','frame extractor','scene detector','OCR','DeepStream analyzer']],['Editing',['trim','concat','crop','normalize-audio','subtitle','transcode']],['Composition',['Remotion','caption compositor','transition compositor','graphics compositor']],['Generation',['image generator','video generator','voice generator','music generator']],['Validation',['integrity checker','sync checker','duration checker','black-frame detector','quality evaluator']]] as Array<[string,string[]]>;return <><Banner icon={Code2} title="Media Tool Registry" detail="The Governor speaks through safe media operations rather than raw terminal commands." tone="amber"/><div className="tool-registry-grid">{categories.map(([category,items])=><Card className="media-tool-category" key={category}><div className="category-head"><span className="panel-kicker">{category}</span><Pill tone={category==='Generation'?'warning':'positive'}>{items.length} tools</Pill></div>{(items as string[]).map(item=><button className="tool-registry-row" key={item} onClick={()=>inspect('media-tool',item,`${item} is exposed as a governed Media Tool API operation. It requires a policy decision before execution.`)}><span className="tool-status-dot"/><b>{item}</b><ChevronRight size={14}/></button>)}</Card>)}</div><Card><Head title="Tool API examples" sub="Human-readable intent becomes a controlled operation"/><div className="api-example-grid"><div><span className="panel-kicker">Intent</span><p>Trim Scene 4 from 00:12.3 to 00:16.7.</p></div><ArrowRight size={15}/><div><span className="panel-kicker">Operation</span><code>media.trim(input, start, end, output)</code></div><ArrowRight size={15}/><div><span className="panel-kicker">Policy</span><Pill tone="positive">MEDIA_WRITE / Allowed</Pill></div></div><button className="primary-button" onClick={()=>go('terminal')}><Terminal size={15}/> Open Flujo Terminal</button></Card></>}

export function Composition({go,inspect,announce}:SurfaceProps){const [rendered,setRendered]=useState(false);return <><Banner icon={Sparkles} title="Remotion Composition Lab" detail="Edit a working composition copy, render it in a sandbox, compare the diff, then promote only after QA." tone="coral"/><div className="composition-header"><div><span className="panel-kicker">Production composition</span><h2>AdTemplate.tsx <span>v17</span></h2><p>Video + code + assets + parameters remain reproducible.</p></div><Pill tone="warning">Working copy</Pill></div><div className="section-grid two-one"><Card><Head title="Composition patch" sub="workspace / workflow_9283 / composition.patch.tsx"/><div className="code-block composition-code"><div className="code-line"><span>01</span><b>+ caption</b><p>y: 920, kinetic: 'rise', emphasis: 'citrus'</p></div><div className="code-line"><span>02</span><b>+ transition</b><p>between: ['scene-03','scene-04'], duration: 12</p></div><div className="code-line"><span>03</span><b>- audio</b><p>volume: 0.82</p></div></div><div className="hero-actions"><button className="primary-button" onClick={()=>{setRendered(true);announce('Sandbox composition render completed locally.')}}><Play size={15}/> {rendered?'Rendered':'Render sandbox copy'}</button><button className="secondary-button" onClick={()=>inspect('composition','Composition diff','The working copy adds kinetic captions and a smoother transition, while lowering the audio level.')}>Inspect diff</button></div></Card><Card><Head title="Render gates" sub="Promotion path"/><Row icon={FlaskConical} title="Sandbox render" detail="Isolated composition copy" status={rendered?'Passed':'Pending'} tone={rendered?'positive':'warning'}/><Row icon={ClipboardCheck} title="QA" detail="Black frames, sync, duration, quality" status="Pending" tone="neutral" click={()=>go('qa')}/><Row icon={GitCompare} title="Diff review" detail="Human approval before promote" status="Required" tone="warning"/><Row icon={Archive} title="Promote" detail="Write to production composition" status="Gated" tone="neutral"/></Card></div><Card><Head title="Reproducibility record" sub="The final render remains inspectable"/><div className="repro-grid"><span>Assets <b>image_12 · video_33 · voice_7 · music_4</b></span><span>Skill <b>food-ad-v6</b></span><span>Parameters <b>9:16 · 30s · 24fps</b></span><span>Source <b>Northstar / Citrus at Dusk</b></span></div></Card></>}

export function TerminalSurface({announce,inspect}:SurfaceProps){const [command,setCommand]=useState('ffprobe scene_04.mp4');const [ran,setRan]=useState(false);const [host,setHost]=useState(false);return <><Banner icon={Terminal} title="Flujo Terminal" detail="A transparent, sandboxed terminal for debugging and reviewing agent actions. It is not the host shell." tone="slate"/><div className="terminal-layout"><Card className="terminal-card"><div className="terminal-head"><span><span className="terminal-led"/> sandbox://workflow_9283</span><Pill tone={host?'warning':'positive'}>{host?'Advanced host mode':'Sandbox only'}</Pill></div><div className="terminal-output"><div><span className="terminal-prompt">$</span> ffprobe scene_04.mp4</div>{ran&&<><p>Duration: 00:04.23</p><p>FPS: 30</p><p>Audio: yes</p><p>Resolution: 1080x1920</p><p className="terminal-success">✓ command completed</p></>}</div><div className="terminal-input"><span>$</span><input value={command} onChange={e=>setCommand(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){setRan(true);announce('Sandbox command completed locally.')}}}/><button onClick={()=>{setRan(true);announce('Sandbox command completed locally.')}}><Play size={14}/></button></div><div className="terminal-foot"><span>Working directory: .flujo/runtime/workflow_9283</span><button onClick={()=>inspect('terminal','Command permission','This command is read-only and scoped to the workflow runtime directory.')}>Why allowed?</button></div></Card><Card><Head title="Permission gate" sub="Every command gets a reason"/><div className="reason-card"><span className="panel-kicker">INTENT</span><b>Inspect media metadata before render</b><span className="panel-kicker">EXPECTED</span><b>Duration, FPS, audio, resolution</b><span className="panel-kicker">SCOPE</span><b>.flujo/runtime/workflow_9283/input</b><span className="panel-kicker">RISK</span><Pill tone="positive">LOW</Pill></div><div className="terminal-permissions"><Toggle label="Host tools available" enabled={host} onClick={()=>{setHost(!host);announce(host?'Host access disabled.':'Host access requested and still gated.')}}/><span className="terminal-note">Host shell access is opt-in and remains separately controlled from file and media permissions.</span></div><button className="soft-action" onClick={()=>announce('Terminal action copied to the audit log.')}>Write audit record <ArrowRight size={14}/></button></Card></div><Card><Head title="Allowed in this sandbox" sub="Explicit deny rules are always stronger than model instructions"/><div className="allow-deny-grid"><div><Pill tone="positive">ALLOW</Pill><p>Read project files, create temporary files, modify media, render artifacts, inspect logs.</p></div><div><Pill tone="critical">DENY</Pill><p>System directories, registry changes, credential extraction, arbitrary network shell, unknown executable downloads.</p></div></div></Card></>}

export function Replay({go,inspect}:SurfaceProps){const events=[['13:04:22','Governor analyzed Scene 7','Decision'],['13:04:25','Cosmos consulted','Advisor'],['13:04:28','Model disagreement detected','Warning'],['13:04:31','Temporary frame-analysis tool created','Tool'],['13:04:36','Tool executed in sandbox','Execution'],['13:04:40','Decision updated','Decision'],['13:04:48','FFmpeg normalization','Media'],['13:04:51','Remotion render','Composition'],['13:05:12','QA passed','Verification']];return <><Banner icon={History} title="Agent Activity Replay" detail="Watch how Flujo worked, from Governor decision through tool creation, media manipulation, render, and QA." tone="coral"/><div className="replay-header"><div><span className="panel-kicker">Workflow #8821</span><h2>Citrus at Dusk / Scene 07</h2><p>Replay is read-only and grounded in the audit log.</p></div><button className="primary-button" onClick={()=>announceReplay(inspect)}> <Play size={15}/> Play replay</button></div><Card className="replay-card"><Head title="Timeline" sub="13:04:22 -> 13:05:12"/>{events.map(([time,event,kind])=><button className="replay-row" key={time} onClick={()=>inspect('replay',event,`${kind} event at ${time}. Full stdout, stderr, permissions, and resource usage will attach here.`)}><time>{time}</time><span className={`replay-dot ${kind.toLowerCase()}`}/><span><b>{event}</b><small>{kind} event · inspect audit record</small></span><ChevronRight size={14}/></button>)}</Card><Card><Head title="Replay controls" sub="Never mutates the original workflow"/><div className="security-strip"><Pill tone="positive"><Check size={13}/> Read-only</Pill><Pill tone="positive"><Check size={13}/> Secrets redacted</Pill><Pill tone="warning"><CircleAlert size={13}/> Host actions excluded</Pill></div><button className="soft-action" onClick={()=>go('terminal')}><Terminal size={14}/> Open terminal audit</button></Card></>}
