function TreeLine({label,indent=false,tone='neutral'}:{label:string;indent?:boolean;tone?:string}){return <button className={`tree-line ${indent?'indent':''}`}><span className={`tree-dot ${tone}`}/><b>{label}</b><ChevronRight size={13}/></button>}

export function MemorySources({go,inspect}:SurfaceProps){const [vault,setVault]=useState(true);return <><Banner icon={History} title="Memory Adapter" detail="Search Flujo Memory, an optional Obsidian vault, project files, conversation memory, and user preferences through explicit permissions." tone="sage"/><div className="memory-adapter-grid"><Card><Head title="Connected sources" sub="The Governor asks the Memory Service, not folders directly"/><Row icon={History} title="Flujo Memory" detail=".flujo/memory/ Markdown + YAML" status="Connected" tone="positive"/><Row icon={Archive} title="Obsidian Vault" detail="Optional vault adapter" status={vault?'Connected':'Off'} tone={vault?'sage':'neutral'} click={()=>setVault(!vault)}/><Row icon={FileText} title="Project files" detail="Permitted README and brand notes" status="Scoped" tone="amber"/><Row icon={MessageCircle} title="Conversation memory" detail="Current Creative Chat only" status="Scoped" tone="slate"/></Card><Card><Head title="Allowed vault folders" sub="Flujo indexes only what the user explicitly permits"/><div className="vault-checks">{['Projects','Brand Knowledge','Personal','Private','Finance'].map((x,i)=><label key={x}><input type="checkbox" defaultChecked={i<2}/><span>{x}</span></label>)}</div><button className="primary-button full-button" onClick={()=>inspect('memory','Vault permissions','Only selected folders will be indexed. Flujo does not crawl the entire vault blindly.')}>Review permission scope</button></Card></div><Card><Head title="Memory provenance" sub="Every remembered preference stays traceable"/><div className="memory-provenance"><span className="provenance-source"><History size={16}/><b>Warm cinematic lighting</b></span><span>Source <b>Obsidian / Brand / Visual Style.md</b></span><span>Confidence <b>0.94</b></span><span>Last updated <b>August 20, 2026</b></span><button className="text-button" onClick={()=>go('evidence')}>Add to Evidence Graph <ArrowRight size={14}/></button></div></Card></>}

export function PermissionCenter({announce,inspect}:SurfaceProps){const permissions=[['FILE_READ','Read permitted project files',true],['FILE_WRITE','Create and modify project files',true],['MEDIA_READ','Read media inside the project boundary',true],['MEDIA_WRITE','Modify media and write generated artifacts',true],['PROCESS_EXECUTE','Run approved tools in sandbox',true],['NETWORK_ACCESS','Reach external providers',false],['PUBLISH','Publish to social accounts',false],['SYSTEM_ACCESS','Modify host system',false]] as Array<[string,string,boolean]>;return <><Banner icon={ShieldCheck} title="Permission Center" detail="Keep file access, media access, process execution, networking, publishing, and system access separate." tone="slate"/><div className="permission-grid">{permissions.map(([name,detail,enabled])=><div className={`permission-row ${enabled?'enabled':''}`} key={name}><span className="permission-lock"><LockKeyhole size={15}/></span><span><b>{name as string}</b><small>{detail as string}</small></span><Pill tone={enabled?'positive':'critical'}>{enabled?'Allowed':'Denied'}</Pill><button className="icon-button subtle" onClick={()=>inspect('permission',name as string,`${detail as string}. The model cannot grant itself this permission.`)}><ChevronRight size={14}/></button></div>)}</div><Card><Head title="Safe defaults" sub="Sandbox only is the default local mode"/><div className="security-strip"><Pill tone="positive"><Check size={13}/> No root access</Pill><Pill tone="positive"><Check size={13}/> No secret logging</Pill><Pill tone="positive"><Check size={13}/> No arbitrary network shell</Pill><Pill tone="warning"><CircleAlert size={13}/> Host mode opt-in</Pill></div><button className="soft-action" onClick={()=>announce('Permission policy explanation opened locally.')}>Explain permission hierarchy <ArrowRight size={14}/></button></Card></>}
